import { signalAddressKey } from 'zapo-js/protocol';
import { decodeSignalSessionRecord, encodeSignalSessionRecord, toSignalAddressParts } from 'zapo-js/signal';
import { asNumber, asString, resolvePositive } from 'zapo-js/util';
import { BaseSqliteStore } from './BaseSqliteStore.js';
import { repeatSqlToken } from './sql-utils.js';
const DEFAULTS = Object.freeze({
    hasSessionBatchSize: 250
});
export class WaSessionSqliteStore extends BaseSqliteStore {
    constructor(options, storeOptions = {}) {
        super(options, ['signal']);
        this.hasSessionBatchSize = resolvePositive(storeOptions.hasSessionBatchSize, DEFAULTS.hasSessionBatchSize, 'signal.sqlite.hasSessionBatchSize');
    }
    async hasSession(address) {
        const db = await this.getConnection();
        const target = toSignalAddressParts(address);
        return (db.get(`SELECT 1 AS has_session
                 FROM signal_session
                 WHERE session_id = ? AND user = ? AND server = ? AND device = ?
                 LIMIT 1`, [this.options.sessionId, target.user, target.server, target.device]) !== null);
    }
    async hasSessions(addresses) {
        if (addresses.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const targets = new Array(addresses.length);
        for (let index = 0; index < addresses.length; index += 1) {
            targets[index] = toSignalAddressParts(addresses[index]);
        }
        const existingKeys = new Set();
        for (let start = 0; start < targets.length; start += this.hasSessionBatchSize) {
            const end = Math.min(start + this.hasSessionBatchSize, targets.length);
            const batchLength = end - start;
            const filters = repeatSqlToken('(user = ? AND server = ? AND device = ?)', batchLength, ' OR ');
            const params = [this.options.sessionId];
            for (let index = start; index < end; index += 1) {
                const target = targets[index];
                params.push(target.user, target.server, target.device);
            }
            const rows = db.all(`SELECT user, server, device
                 FROM signal_session
                 WHERE session_id = ? AND (${filters})`, params);
            for (const row of rows) {
                existingKeys.add(signalAddressKey({
                    user: asString(row.user, 'signal_session.user'),
                    server: asString(row.server, 'signal_session.server'),
                    device: asNumber(row.device, 'signal_session.device')
                }));
            }
        }
        const hasByTarget = new Array(targets.length);
        for (let index = 0; index < targets.length; index += 1) {
            hasByTarget[index] = existingKeys.has(signalAddressKey(targets[index]));
        }
        return hasByTarget;
    }
    async getSession(address) {
        const db = await this.getConnection();
        const target = toSignalAddressParts(address);
        const row = db.get(`SELECT user, server, device, record
             FROM signal_session
             WHERE session_id = ? AND user = ? AND server = ? AND device = ?`, [this.options.sessionId, target.user, target.server, target.device]);
        return row ? decodeSignalSessionRecord(row.record) : null;
    }
    async getSessionsBatch(addresses) {
        if (addresses.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const targets = new Array(addresses.length);
        for (let index = 0; index < addresses.length; index += 1) {
            targets[index] = toSignalAddressParts(addresses[index]);
        }
        const byAddressKey = new Map();
        for (let start = 0; start < targets.length; start += this.hasSessionBatchSize) {
            const end = Math.min(start + this.hasSessionBatchSize, targets.length);
            const batchLength = end - start;
            const filters = repeatSqlToken('(user = ? AND server = ? AND device = ?)', batchLength, ' OR ');
            const params = [this.options.sessionId];
            for (let index = start; index < end; index += 1) {
                const target = targets[index];
                params.push(target.user, target.server, target.device);
            }
            const rows = db.all(`SELECT user, server, device, record
                 FROM signal_session
                 WHERE session_id = ? AND (${filters})`, params);
            for (const row of rows) {
                byAddressKey.set(signalAddressKey({
                    user: asString(row.user, 'signal_session.user'),
                    server: asString(row.server, 'signal_session.server'),
                    device: asNumber(row.device, 'signal_session.device')
                }), decodeSignalSessionRecord(row.record));
            }
        }
        const sessions = new Array(targets.length);
        for (let index = 0; index < targets.length; index += 1) {
            sessions[index] = byAddressKey.get(signalAddressKey(targets[index])) ?? null;
        }
        return sessions;
    }
    async setSession(address, session) {
        const db = await this.getConnection();
        const target = toSignalAddressParts(address);
        this.upsertSession(db, target, session);
    }
    async setSessionsBatch(entries) {
        if (entries.length === 0) {
            return;
        }
        await this.withTransaction((db) => {
            for (let index = 0; index < entries.length; index += 1) {
                const entry = entries[index];
                this.upsertSession(db, toSignalAddressParts(entry.address), entry.session);
            }
        });
    }
    async deleteSession(address) {
        const db = await this.getConnection();
        const target = toSignalAddressParts(address);
        db.run(`DELETE FROM signal_session
             WHERE session_id = ? AND user = ? AND server = ? AND device = ?`, [this.options.sessionId, target.user, target.server, target.device]);
    }
    async clear() {
        await this.withTransaction((db) => {
            db.run('DELETE FROM signal_session WHERE session_id = ?', [this.options.sessionId]);
        });
    }
    upsertSession(db, target, session) {
        db.run(`INSERT INTO signal_session (
                session_id,
                user,
                server,
                device,
                record
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(session_id, user, server, device) DO UPDATE SET
                record=excluded.record`, [
            this.options.sessionId,
            target.user,
            target.server,
            target.device,
            encodeSignalSessionRecord(session)
        ]);
    }
}
